import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def comparisons(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    targets = torch.tensor([[0, 1], [1, 0]])
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(targets)}
dataset = synth.Spec("cpo-preferences", generator=comparisons, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class PairLanguageModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=12)
    def forward(self, inputs):
        return {"pair_logits": self.network(inputs).reshape(-1, 2, 2, 3)}
trainer = Trainer(PairLanguageModel(), train, recipe="structured-objective", recipe_config={"loss": "cpo", "bindings": {"logits_or_prediction": {"output": "pair_logits"}, "targets": {"batch": "targets"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
